mod field_api_capnp { include!(concat!(env!("OUT_DIR"), "/field_api_capnp.rs")); }
use capnp::field_api::{Message, MessageView, Entry};
use field_api_capnp::api::{Person, Address};
fn main() {
let mut loader=capnp::schema_loader::SchemaLoader::default();
loader.load_compiled_type_and_dependencies::<field_api_capnp::person::Owned>().unwrap();
let schema=loader.get(<field_api_capnp::person::Reader<'static> as capnp::traits::HasTypeId>::TYPE_ID).unwrap();
let mut message=capnp::message::Builder::new_default();
let root=capnp::schema_loader::dynamic::Builder::init(message.init_root(),schema).unwrap();
let (mut root,token)=root.with_orphanage();
let mut owner=root.disown_named("address",&token).unwrap();
token.in_struct(&mut root).unwrap().edit(&mut owner, |v| {
        let capnp::schema_loader::dynamic::orphan::Editor::Struct(mut b)=v else {panic!()};
        b.set_named("city",capnp::schema_loader::dynamic::Value::Text("loaded".into()))
    }).unwrap();root.adopt_named("previousAddress",owner).unwrap();
}

